AAsset *AAssetManager_open(AAssetManager*m,const char*name,int mode){AAsset*a;char p[3000];FILE*f;(void)mode;if(snprintf(p,sizeof p,"%s/%s",m->root,name)<0)return NULL;f=fopen(p,"rb");if(!f)return NULL;a=calloc(1,sizeof(*a));if(!a){fclose(f);return NULL;}a->f=f;_fseeki64(f,0,SEEK_END);a->n=_ftelli64(f);rewind(f);return a;}
int AAsset_read(AAsset*a,void*p,size_t n){return (int)fread(p,1,n,a->f);}
off64_t AAsset_getLength64(AAsset*a){return a->n;}
const void *AAsset_getBuffer(AAsset*a){if(!a->buffer){off64_t at=_ftelli64(a->f);a->buffer=malloc((size_t)a->n);if(!a->buffer)return NULL;rewind(a->f);if(fread(a->buffer,1,(size_t)a->n,a->f)!=(size_t)a->n){free(a->buffer);a->buffer=NULL;} _fseeki64(a->f,at,SEEK_SET);}return a->buffer;}
