/* Honest fixture backend: no UI/item/equip/door capability is supplied. It may
 * acknowledge ONLY batches requiring no external services and zero effects.
 * Actual source owner registry, Lua, inventory, timers and durable file live in
 * the production C host; actual actor/collision reservation is not substituted. */
static int available(void*c,uint32_t required,char*e,size_t n){(void)c;if(!required)return 0;snprintf(e,n,"GPU fixture has no UI/item/equip/door services");return 1;}
static int prepare(void*c,const oa_creator_game_batch*b,void**token,char*e,size_t n){(void)c;*token=NULL;if(b->required_capabilities||b->effect_count){snprintf(e,n,"Unprovided actor/UI effect rejected");return 1;}backend_prepares++;return 0;}
static void commit(void*c,void*t){(void)c;(void)t;backend_commits++;}
static void abort_batch(void*c,void*t){(void)c;(void)t;}
